-- Job Match: contenido de demostración, no son personas ni vacantes reales.
-- Todos los registros llevan is_demo=true, no tienen propietario de auth.users y no pueden generar matches.
-- Es idempotente: usa IDs deterministas y se puede retirar con supabase/remove_demo_data.sql.
-- Ejecutar solo si se desea mostrar contenido de muestra claramente identificado en la app.
begin;

on conflict (id) do update set user_id=null,full_name=excluded.full_name,age=excluded.age,photo_path=excluded.photo_path,desired_position=excluded.desired_position,sector=excluded.sector,experience_years=excluded.experience_years,availability=excluded.availability,availability_note=excluded.availability_note,skills=excluded.skills,bio=excluded.bio,city=excluded.city,lat=excluded.lat,lng=excluded.lng,is_active=true,is_demo=true,is_boosted=false,boost_expires_at=null,updated_at=now();

on conflict (id) do update set company_id=null,business_name=excluded.business_name,business_image_path=null,position=excluded.position,sector=excluded.sector,salary_text=excluded.salary_text,salary_amount=excluded.salary_amount,salary_frequency=excluded.salary_frequency,salary_kind=excluded.salary_kind,salary_min=excluded.salary_min,salary_max=excluded.salary_max,salary_period=excluded.salary_period,shift_type=excluded.shift_type,schedule=excluded.schedule,benefits=excluded.benefits,description=excluded.description,city=excluded.city,address_approx=excluded.address_approx,lat=excluded.lat,lng=excluded.lng,is_active=true,is_demo=true,is_boosted=false,boost_expires_at=null,expires_at=now()+interval '14 days',updated_at=now();

commit;
